// Omniflow batch 1361 - ROUTER + AGENTS ENGINE (AI agent personas +
// agent-target routing). portal_agents (NEW): named AI personas
// (tone + free-form instructions + escalation user id), versioned
// (every save snapshots to portal_agent_versions), soft-archived
// (past conversations keep their context). Human-only API (API keys
// 403). Routing upgrade: rules carry target_type ('user' | 'agent')
// + agent_id (lazy ALTER, data preserved); agent rules assign the
// conversation to a persona via portal_conversation_agents, and the
// Business Brain reads it through agent_for_conversation (read-only,
// fail-soft) and answers in that persona (grounding agent_persona,
// tone override). Web: portal.ts Agent client + RoutingRule agent
// fields, agents BFF (list/create/update/archive), routing BFF
// target validation, Team page "AI agents & routing" section.
// Rig: test_agents 41 + test_brain 96 + test_growth_pack pins.
// Whole-file marker-guarded ops (backup on drift, .pre_router.bak);
// idempotent; dir-conflicts quarantined.

import fs from "fs";
const BACKUP_TAG = ".pre_router.bak";
let applied = 0, already = 0, warnings = 0;
function writeNewRepair(repoPath, marker, isCp, content) {
  try {
  let existed = false;
  if (fs.existsSync(repoPath)) {
    if (fs.statSync(repoPath).isDirectory()) {
      let target = repoPath + ".dir_conflict.bak";
      let n = 1;
      while (fs.existsSync(target)) { target = repoPath + ".dir_conflict.bak." + n; n++; }
      fs.renameSync(repoPath, target);
      console.log("! " + repoPath + " was a DIRECTORY on this machine - renamed to " + target + "; writing the real file.");
      warnings++;
    } else existed = true;
  }
  if (!existed) {
    const cut = Math.max(repoPath.lastIndexOf("/"), repoPath.lastIndexOf("\\"));
    if (cut > 0) fs.mkdirSync(repoPath.slice(0, cut), { recursive: true });
    fs.writeFileSync(repoPath, content, "utf8");
    console.log("+ " + repoPath + " (restored - was missing)");
    applied++;
    return;
  }
  const original = fs.readFileSync(repoPath, "utf8").replace(/\r\n/g, "\n");
  if (original.includes(marker)) {
    console.log("= " + repoPath + " (already correct)");
    already++;
    return;
  }
  const backup = repoPath + BACKUP_TAG;
  if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
  fs.writeFileSync(repoPath, content, "utf8");
  console.log("+ " + repoPath + " (REPAIRED - old copy kept as " + BACKUP_TAG + ")");
  applied++;
  } catch (err) {
    console.log("X " + repoPath + " FAILED: " + err.message);
    warnings++;
  }
}
writeNewRepair("omniflow-backend-patch/portal_agents.py", "portal_agent_versions", false,
    "\"\"\"AI Agents engine (MASTER-UPGRADE Router+Agents).\n\nAgents are NAMED AI PERSONAS the owner creates - e.g. \"Sales Aunty\"\n(warm, upsells), \"Support Pro\" (formal, policy-strict). Each agent:\n\n  * has a tone + free-form instructions the Business Brain follows when\n    the conversation belongs to it (portal_brain reads the agent through\n    agent_for_conversation - read-only, fail-soft);\n  * can be a ROUTING TARGET: routing rules with target_type='agent'\n    assign matching conversations to the agent (portal_routing);\n  * carries an escalation_user_id (the teammate complex cases go to);\n  * is versioned: every save writes a portal_agent_versions snapshot\n    row, so config drift is always explainable.\n\nFail-soft everywhere: a missing table, a bad id or an inactive agent\njust means \"no agent\" - the brain keeps its default persona and routing\nkeeps working with user targets. Owner-only API (API keys get 403) -\nagents steer the AI and must never be drivable by automation keys.\n\"\"\"\n\nimport json\nimport logging\nimport os\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\n\nlogger = logging.getLogger(\"omniflow.portal-agents\")\n\nbp = Blueprint(\"portal_agents\", __name__, url_prefix=\"/api/v1/portal\")\n\nAGENTS_TABLE = \"portal_agents\"\nVERSIONS_TABLE = \"portal_agent_versions\"\nCONV_AGENTS_TABLE = \"portal_conversation_agents\"\n\nMAX_AGENTS = int(os.environ.get(\"OF_AGENTS_MAX\", \"10\") or 10)\nMAX_NAME_CHARS = 60\nMAX_TONE_CHARS = 120\nMAX_INSTRUCTIONS_CHARS = int(\n    os.environ.get(\"OF_AGENT_INSTRUCTIONS_MAX\", \"1000\") or 1000)\n\n_DDL_READY = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_agents (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  name TEXT NOT NULL,\n  tone TEXT NOT NULL DEFAULT '',\n  instructions TEXT NOT NULL DEFAULT '',\n  escalation_user_id BIGINT,\n  is_active BOOLEAN NOT NULL DEFAULT TRUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_agents\n  ON portal_agents (client_id, is_active, id DESC);\nCREATE TABLE IF NOT EXISTS portal_agent_versions (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  agent_id BIGINT NOT NULL,\n  version INTEGER NOT NULL DEFAULT 1,\n  snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  UNIQUE (client_id, agent_id, version)\n);\nCREATE TABLE IF NOT EXISTS portal_conversation_agents (\n  client_id BIGINT NOT NULL,\n  conversation_id BIGINT NOT NULL,\n  agent_id BIGINT NOT NULL,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  PRIMARY KEY (client_id, conversation_id)\n);\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    _DDL_READY = True\n\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\ndef _shape(row: Dict[str, Any]) -> Dict[str, Any]:\n    escalation = row.get(\"escalation_user_id\")\n    return {\"id\": int(row.get(\"id\") or 0),\n            \"name\": str(row.get(\"name\") or \"\"),\n            \"tone\": str(row.get(\"tone\") or \"\"),\n            \"instructions\": str(row.get(\"instructions\") or \"\"),\n            \"escalation_user_id\": int(escalation) if escalation else None,\n            \"is_active\": bool(row.get(\"is_active\")),\n            \"updated_at\": str(row.get(\"updated_at\") or \"\")}\n\n\n# ---------------------------------------------------------------------------\n# Helpers (read-side, fail-soft) - used by routing + the brain\n# ---------------------------------------------------------------------------\n\ndef load_agent(cur, client_id: int, agent_id: int) -> Optional[Dict[str, Any]]:\n    \"\"\"One active agent row (None when missing/foreign/inactive).\"\"\"\n    try:\n        cur.execute(\n            \"SELECT id, name, tone, instructions, escalation_user_id,\"\n            \" is_active, updated_at FROM \" + portal_db._q(AGENTS_TABLE) +\n            \" WHERE id = %s AND client_id = %s AND is_active = TRUE\"\n            \" LIMIT 1\",\n            (agent_id, client_id),\n        )\n        rows = portal_db.rows(cur)\n        return _shape(rows[0]) if rows else None\n    except Exception as error:\n        logger.warning(\"load_agent failed: %s\", error)\n        return None\n\n\ndef agent_for_conversation(cur, client_id: int,\n                           conversation_id: int) -> Optional[Dict[str, Any]]:\n    \"\"\"The agent a conversation is currently assigned to (the brain's\n    read path - fail-soft: any problem means no agent).\"\"\"\n    try:\n        cur.execute(\n            \"SELECT a.id, a.name, a.tone, a.instructions,\"\n            \" a.escalation_user_id, a.is_active, a.updated_at\"\n            \" FROM \" + portal_db._q(CONV_AGENTS_TABLE) + \" ca\"\n            \" JOIN \" + portal_db._q(AGENTS_TABLE) + \" a ON a.id = ca.agent_id\"\n            \" WHERE ca.client_id = %s AND ca.conversation_id = %s\"\n            \" AND a.is_active = TRUE LIMIT 1\",\n            (client_id, conversation_id),\n        )\n        rows = portal_db.rows(cur)\n        return _shape(rows[0]) if rows else None\n    except Exception as error:\n        logger.warning(\"agent_for_conversation failed: %s\", error)\n        return None\n\n\ndef assign_agent(cur, client_id: int, conversation_id: int,\n                 agent_id: int) -> None:\n    \"\"\"Record/replace the conversation's agent (routing's write path).\"\"\"\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(CONV_AGENTS_TABLE) +\n        \" (client_id, conversation_id, agent_id, updated_at)\"\n        \" VALUES (%s, %s, %s, NOW())\"\n        \" ON CONFLICT (client_id, conversation_id) DO UPDATE SET\"\n        \" agent_id = EXCLUDED.agent_id, updated_at = NOW()\",\n        (client_id, conversation_id, agent_id),\n    )\n\n\n# ---------------------------------------------------------------------------\n# Owner API: agents CRUD (human-only)\n# ---------------------------------------------------------------------------\n\n@bp.get(\"/agents\")\ndef list_agents():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"SELECT id, name, tone, instructions, escalation_user_id,\"\n                \" is_active, updated_at FROM \" + portal_db._q(AGENTS_TABLE) +\n                \" WHERE client_id = %s\"\n                \" ORDER BY is_active DESC, id ASC LIMIT %s\",\n                (client_id, max(1, min(50, MAX_AGENTS * 2))),\n            )\n            rows = portal_db.rows(cur)\n            cur.execute(\n                \"SELECT agent_id, COUNT(*) AS versions FROM \" +\n                portal_db._q(VERSIONS_TABLE) +\n                \" WHERE client_id = %s GROUP BY agent_id\",\n                (client_id,),\n            )\n            counts = {int(r.get(\"agent_id\") or 0):\n                      int(r.get(\"versions\") or 0) for r in portal_db.rows(cur)}\n        conn.commit()\n    finally:\n        conn.close()\n    out = []\n    for row in rows:\n        item = _shape(row)\n        item[\"versions\"] = counts.get(item[\"id\"], 0)\n        out.append(item)\n    return jsonify({\"agents\": out}), 200\n\n\ndef _validate_payload(payload: Dict[str, Any]) -> Tuple[Optional[dict], int]:\n    \"\"\"(error_json, status) - (None, 200) when the payload is valid.\"\"\"\n    name = str(payload.get(\"name\") or \"\").strip()\n    tone = str(payload.get(\"tone\") or \"\").strip()\n    instructions = str(payload.get(\"instructions\") or \"\").strip()\n    if not name or len(name) > MAX_NAME_CHARS:\n        return (jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"name is required (max \" + str(MAX_NAME_CHARS)\n                       + \" characters).\"}}), 400)\n    if len(tone) > MAX_TONE_CHARS:\n        return (jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"tone is too long (max \" + str(MAX_TONE_CHARS)\n                       + \").\"}}), 400)\n    if len(instructions) > MAX_INSTRUCTIONS_CHARS:\n        return (jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"instructions are too long (max \"\n                       + str(MAX_INSTRUCTIONS_CHARS) + \").\"}}), 400)\n    escalation = payload.get(\"escalation_user_id\")\n    if escalation is not None:\n        if isinstance(escalation, bool) or not isinstance(escalation, int) \\\n                or escalation <= 0:\n            return (jsonify({\"error\": {\n                \"code\": \"bad_request\",\n                \"message\": \"escalation_user_id must be a positive\"\n                           \" integer.\"}}), 400)\n    return None, 200\n\n\n@bp.post(\"/agents\")\ndef create_agent():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    invalid, status = _validate_payload(payload)\n    if invalid:\n        return invalid, status\n    name = str(payload.get(\"name\") or \"\").strip()\n    tone = str(payload.get(\"tone\") or \"\").strip()\n    instructions = str(payload.get(\"instructions\") or \"\").strip()\n    escalation = payload.get(\"escalation_user_id\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"SELECT COUNT(*) AS total FROM \" + portal_db._q(AGENTS_TABLE) +\n                \" WHERE client_id = %s\",\n                (client_id,),\n            )\n            rows = portal_db.rows(cur)\n            if int((rows[0] if rows else {}).get(\"total\") or 0) >= MAX_AGENTS:\n                return jsonify({\"error\": {\n                    \"code\": \"bad_request\",\n                    \"message\": \"Max \" + str(MAX_AGENTS) + \" agents.\"}}), 400\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(AGENTS_TABLE) +\n                \" (client_id, name, tone, instructions, escalation_user_id)\"\n                \" VALUES (%s, %s, %s, %s, %s) RETURNING id\",\n                (client_id, name[:MAX_NAME_CHARS], tone[:MAX_TONE_CHARS],\n                 instructions[:MAX_INSTRUCTIONS_CHARS], escalation),\n            )\n            rows = portal_db.rows(cur)\n            agent_id = int((rows[0] if rows else {}).get(\"id\") or 0)\n            snapshot = {\"name\": name, \"tone\": tone,\n                        \"instructions\": instructions,\n                        \"escalation_user_id\": escalation}\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(VERSIONS_TABLE) +\n                \" (client_id, agent_id, version, snapshot)\"\n                \" VALUES (%s, %s, 1, CAST(%s AS JSONB))\",\n                (client_id, agent_id,\n                 json.dumps(snapshot, ensure_ascii=False)),\n            )\n            portal_db.log_action(\n                cur, client_id, \"agents.saved\", \"human\",\n                principal.get(\"user_id\"), None,\n                (\"Agent created: \" + name)[:200],\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"agent\": {\"id\": agent_id, \"name\": name, \"tone\": tone,\n                              \"instructions\": instructions,\n                              \"escalation_user_id\": escalation,\n                              \"is_active\": True, \"versions\": 1}}), 200\n\n\n@bp.put(\"/agents/<int:agent_id>\")\ndef update_agent(agent_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    invalid, status = _validate_payload(payload)\n    if invalid:\n        return invalid, status\n    name = str(payload.get(\"name\") or \"\").strip()\n    tone = str(payload.get(\"tone\") or \"\").strip()\n    instructions = str(payload.get(\"instructions\") or \"\").strip()\n    escalation = payload.get(\"escalation_user_id\")\n    is_active = payload.get(\"is_active\", True)\n    if not isinstance(is_active, bool):\n        is_active = bool(is_active)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"UPDATE \" + portal_db._q(AGENTS_TABLE) +\n                \" SET name = %s, tone = %s, instructions = %s,\"\n                \" escalation_user_id = %s, is_active = %s, updated_at = NOW()\"\n                \" WHERE id = %s AND client_id = %s RETURNING id\",\n                (name[:MAX_NAME_CHARS], tone[:MAX_TONE_CHARS],\n                 instructions[:MAX_INSTRUCTIONS_CHARS], escalation,\n                 is_active, agent_id, client_id),\n            )\n            rows = portal_db.rows(cur)\n            if not rows:\n                conn.rollback()\n                return jsonify({\"error\": {\n                    \"code\": \"not_found\",\n                    \"message\": \"No such agent in this workspace.\"}}), 404\n            snapshot = {\"name\": name, \"tone\": tone,\n                        \"instructions\": instructions,\n                        \"escalation_user_id\": escalation,\n                        \"is_active\": is_active}\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(VERSIONS_TABLE) +\n                \" (client_id, agent_id, version, snapshot)\"\n                \" SELECT %s, %s, COALESCE(MAX(version), 0) + 1, CAST(%s AS\"\n                \" JSONB) FROM \" + portal_db._q(VERSIONS_TABLE) +\n                \" WHERE client_id = %s AND agent_id = %s\",\n                (client_id, agent_id,\n                 json.dumps(snapshot, ensure_ascii=False),\n                 client_id, agent_id),\n            )\n            portal_db.log_action(\n                cur, client_id, \"agents.saved\", \"human\",\n                principal.get(\"user_id\"), None,\n                (\"Agent updated: \" + name)[:200],\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.delete(\"/agents/<int:agent_id>\")\ndef archive_agent(agent_id: int):\n    \"\"\"Soft delete: agents steer past conversations' context - they are\n    archived, never destroyed (data-preserving).\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"UPDATE \" + portal_db._q(AGENTS_TABLE) +\n                \" SET is_active = FALSE, updated_at = NOW()\"\n                \" WHERE id = %s AND client_id = %s RETURNING id\",\n                (agent_id, client_id),\n            )\n            rows = portal_db.rows(cur)\n            if not rows:\n                conn.rollback()\n                return jsonify({\"error\": {\n                    \"code\": \"not_found\",\n                    \"message\": \"No such agent in this workspace.\"}}), 404\n            portal_db.log_action(\n                cur, client_id, \"agents.archived\", \"human\",\n                principal.get(\"user_id\"), None,\n                (\"Agent archived (id \" + str(agent_id) + \")\")[:200],\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True}), 200\n");

writeNewRepair("omniflow-backend-patch/portal_routing.py", "ADD COLUMN IF NOT EXISTS target_type", false,
    "\"\"\"Router engine v1: deterministic keyword rules that assign inbound\nchats to a TEAM MEMBER or an AI AGENT (round the clock, no LLM call).\n\nUpgrade (Router+Agents engine): rules carry target_type - 'user' (the\noriginal teammate assignment, unchanged behaviour) or 'agent' (assigns\nthe conversation to a named AI persona from portal_agents; the brain\nthen answers in that agent's tone + instructions). Agent rules only\nfire while the agent is active (LEFT JOIN filter). Inactive/unknown\nagents degrade to no-assignment - routing never blocks the ingest.\"\"\"\n\nimport logging\n\nfrom flask import Blueprint, jsonify, request\n\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\nimport portal_db\n\nbp = Blueprint(\"portal_routing\", __name__, url_prefix=\"/api/v1/portal\")\n\nlogger = logging.getLogger(__name__)\n\nRULES_TABLE = \"portal_routing_rules\"\n\nMAX_RULES = 25\nMAX_MATCH = 60\n\n_ROUTING_DDL_READY = False\n\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}), 401)\n    return principal, None\n\n\ndef _ensure_routing_tables(conn) -> None:\n    global _ROUTING_DDL_READY\n    if _ROUTING_DDL_READY:\n        return\n    with conn.cursor() as cur:\n        cur.execute(\n            \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(RULES_TABLE) +\n            \" (id BIGSERIAL PRIMARY KEY,\"\n            \" client_id BIGINT NOT NULL,\"\n            \" match_text TEXT NOT NULL,\"\n            \" user_id BIGINT NOT NULL,\"\n            \" priority INT NOT NULL DEFAULT 100,\"\n            \" created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())\"\n        )\n        cur.execute(\n            \"ALTER TABLE \" + portal_db._q(RULES_TABLE) +\n            \" ADD COLUMN IF NOT EXISTS target_type TEXT\"\n            \" NOT NULL DEFAULT 'user',\"\n            \" ADD COLUMN IF NOT EXISTS agent_id BIGINT\"\n        )\n        cur.execute(\n            \"CREATE TABLE IF NOT EXISTS portal_conversation_agents (\"\n            \" client_id BIGINT NOT NULL,\"\n            \" conversation_id BIGINT NOT NULL,\"\n            \" agent_id BIGINT NOT NULL,\"\n            \" updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\"\n            \" PRIMARY KEY (client_id, conversation_id))\"\n        )\n        cur.execute(\n            \"CREATE TABLE IF NOT EXISTS portal_agents (\"\n            \" id BIGSERIAL PRIMARY KEY,\"\n            \" client_id BIGINT NOT NULL,\"\n            \" name TEXT NOT NULL,\"\n            \" tone TEXT NOT NULL DEFAULT '',\"\n            \" instructions TEXT NOT NULL DEFAULT '',\"\n            \" escalation_user_id BIGINT,\"\n            \" is_active BOOLEAN NOT NULL DEFAULT TRUE,\"\n            \" created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\"\n            \" updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())\"\n        )\n        cur.execute(\n            \"CREATE INDEX IF NOT EXISTS portal_routing_rules_client_idx ON \"\n            + portal_db._q(RULES_TABLE) + \" (client_id, priority, id)\"\n        )\n    conn.commit()\n    _ROUTING_DDL_READY = True\n\n\n@bp.get(\"/routing/rules\")\ndef list_routing_rules():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_routing_tables(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT r.id, r.match_text, r.user_id, r.priority,\"\n                    \" r.created_at, r.target_type, r.agent_id,\"\n                    \" a.name AS agent_name\"\n                    \" FROM \" + portal_db._q(RULES_TABLE) + \" r\"\n                    \" LEFT JOIN portal_agents a ON a.id = r.agent_id\"\n                    \" WHERE r.client_id = %s\"\n                    \" ORDER BY r.priority ASC, r.id ASC LIMIT 50\",\n                    (principal[\"client_id\"],),\n                )\n                rows = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"routing rules read failed: %s\", error)\n        return jsonify(portal_db.portal_unavailable(error, \"routing rules\")[0]), 503\n    return jsonify({\"rules\": [\n        {\n            \"id\": int(row.get(\"id\") or 0),\n            \"match\": str(row.get(\"match_text\") or \"\"),\n            \"user_id\": row.get(\"user_id\"),\n            \"priority\": int(row.get(\"priority\") or 100),\n            \"created_at\": None,\n            \"target_type\": str(row.get(\"target_type\") or \"user\"),\n            \"agent_id\": row.get(\"agent_id\"),\n            \"agent_name\": row.get(\"agent_name\"),\n        }\n        for row in rows\n    ]}), 200\n\n\n@bp.post(\"/routing/rules\")\ndef add_routing_rule():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    payload = request.get_json(silent=True) or {}\n    match_text = str(payload.get(\"match\") or \"\").strip().lower()[:MAX_MATCH]\n    user_id = payload.get(\"user_id\")\n    priority = payload.get(\"priority\", 100)\n    target_type = str(payload.get(\"target_type\") or \"user\")\n    agent_id = payload.get(\"agent_id\")\n    if not match_text:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"match is required.\"}}), 400\n    if target_type not in (\"user\", \"agent\"):\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"target_type must be\"\n                                             \" user|agent.\"}}), 400\n    if target_type == \"agent\":\n        if isinstance(agent_id, bool) or not isinstance(agent_id, int) \\\n                or agent_id <= 0:\n            return jsonify({\"error\": {\"code\": \"bad_request\",\n                                      \"message\": \"agent_id (positive int) is\"\n                                                 \" required for agent\"\n                                                 \" targets.\"}}), 400\n        user_id = 0\n    elif isinstance(user_id, bool) or not isinstance(user_id, int) \\\n            or user_id <= 0:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"user_id (positive int) is\"\n                                             \" required.\"}}), 400\n    if isinstance(priority, bool) or not isinstance(priority, int) or not (\n            1 <= priority <= 999):\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"priority must be 1-999.\"}}), 400\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_routing_tables(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT COUNT(*) AS total FROM \" +\n                    portal_db._q(RULES_TABLE) + \" WHERE client_id = %s\",\n                    (principal[\"client_id\"],),\n                )\n                count_rows = portal_db.rows(cur)\n                if int((count_rows[0] if count_rows else {}).get(\"total\") or 0) >= MAX_RULES:\n                    return jsonify({\"error\": {\"code\": \"bad_request\",\n                                              \"message\": \"Max \" + str(MAX_RULES)\n                                                         + \" rules.\"}}), 400\n                if target_type == \"agent\":\n                    try:\n                        import portal_agents\n\n                        agent = portal_agents.load_agent(\n                            cur, principal[\"client_id\"], agent_id)\n                    except Exception:\n                        agent = None\n                    if agent is None:\n                        return jsonify({\"error\": {\n                            \"code\": \"bad_request\",\n                            \"message\": \"No such active agent in this\"\n                                       \" workspace.\"}}), 400\n                    target_note = \"agent \" + str(agent_id)\n                else:\n                    target_note = \"user \" + str(user_id)\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(RULES_TABLE) +\n                    \" (client_id, match_text, user_id, priority,\"\n                    \" target_type, agent_id)\"\n                    \" VALUES (%s, %s, %s, %s, %s, %s) RETURNING id\",\n                    (principal[\"client_id\"], match_text, user_id, priority,\n                     target_type, agent_id if target_type == \"agent\"\n                     else None),\n                )\n                created = portal_db.rows(cur)\n                portal_db.log_action(\n                    cur,\n                    principal[\"client_id\"],\n                    \"routing.rule\",\n                    \"customer_user\",\n                    principal.get(\"user_id\"),\n                    None,\n                    (\"Route '\" + match_text + \"' -> \" + target_note)[:200],\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"routing rule save failed: %s\", error)\n        return jsonify(portal_db.portal_unavailable(error, \"routing rule save\")[0]), 503\n    return jsonify({\"ok\": True, \"id\": int((created[0] if created else {})\n                                          .get(\"id\") or 0)}), 200\n\n\n@bp.delete(\"/routing/rules/<int:rule_id>\")\ndef delete_routing_rule(rule_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_routing_tables(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"DELETE FROM \" + portal_db._q(RULES_TABLE) +\n                    \" WHERE id = %s AND client_id = %s RETURNING id\",\n                    (rule_id, principal[\"client_id\"]),\n                )\n                removed = portal_db.rows(cur)\n                if not removed:\n                    return jsonify({\"error\": {\"code\": \"not_found\",\n                                              \"message\": \"Rule not\"\n                                                         \" found.\"}}), 404\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"routing rule delete failed: %s\", error)\n        return jsonify(portal_db.portal_unavailable(error, \"routing rule delete\")[0]), 503\n    return jsonify({\"ok\": True}), 200\n\n\ndef maybe_route(client_id, conversation_id, contact, text, conn) -> None:\n    \"\"\"Ingest hook: assign the conversation on the FIRST matching rule\n    (priority order). Runs inside the ingest transaction; never raises.\n\n    v1: target may be a user (assigned_to on the conversation, unchanged)\n    or an active agent (portal_conversation_agents row; the brain reads\n    it and answers in that persona). The LEFT JOIN keeps agent rules\n    inert while their agent is inactive/missing.\"\"\"\n    value = str(text or \"\").lower()[:500]\n    if not value.strip():\n        return\n    with conn.cursor() as cur:\n        cur.execute(\n            \"SELECT r.id, r.match_text, r.user_id, r.target_type, r.agent_id\"\n            \" FROM \" + portal_db._q(RULES_TABLE) + \" r\"\n            \" LEFT JOIN portal_agents a ON a.id = r.agent_id\"\n            \" AND a.is_active = TRUE\"\n            \" WHERE r.client_id = %s\"\n            \" AND (r.target_type <> 'agent' OR a.id IS NOT NULL)\"\n            \" ORDER BY r.priority ASC, r.id ASC LIMIT 25\",\n            (client_id,),\n        )\n        rules = portal_db.rows(cur)\n        for rule in rules:\n            match_text = str(rule.get(\"match_text\") or \"\").strip().lower()\n            if not match_text or match_text not in value:\n                continue\n            target_type = str(rule.get(\"target_type\") or \"user\")\n            agent_id = rule.get(\"agent_id\")\n            if target_type == \"agent\":\n                if not agent_id:\n                    continue\n                try:\n                    import portal_agents\n\n                    portal_agents.assign_agent(\n                        cur, client_id, conversation_id, int(agent_id))\n                except Exception:\n                    continue\n                label = \"agent \" + str(agent_id)\n            else:\n                user_id = rule.get(\"user_id\")\n                if user_id is None:\n                    continue\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(portal_db.CONV_TABLE) +\n                    \" SET assigned_to = %s\"\n                    \" WHERE id = %s AND client_id = %s\"\n                    \" AND assigned_to IS NULL\",\n                    (user_id, conversation_id, client_id),\n                )\n                label = \"user \" + str(user_id)\n            try:\n                import portal_policy\n\n                portal_policy.rule_fired(\n                    cur, client_id, \"routing\", rule.get(\"id\"),\n                    \"Routing: \" + match_text,\n                    {\"conversation_id\": conversation_id})\n            except Exception:\n                pass\n            portal_db.log_action(\n                cur,\n                client_id,\n                \"chat.routed\",\n                \"automation\",\n                None,\n                conversation_id,\n                (\"Routed to \" + label + \" (match: \" + match_text\n                 + \")\")[:200],\n            )\n            break\n");

writeNewRepair("omniflow-backend-patch/portal_brain.py", "agent_for_conversation(", false,
    "\"\"\"AI Brain v1 (V2 B6): tools, policy, grounding - with provenance.\n\nThe brain is the platform's first intent-driven agent layer. It sits in the\none-reply chain (B2) ahead of the KB gate and can answer inbound customer\nmessages by REASONING OVER TOOLS - all read-only in v1:\n\n  * recent_messages  - the last messages of this conversation;\n  * customer_orders  - the contact's recent checkout links (status/total);\n  * search_kb        - active knowledge-base entries matching the text;\n  * customer_profile - stored language (tone matching).\n\nEvery decision is bounded (OF_BRAIN_MAX_TOOL_CALLS), grounded (the prompt\nmay only use tool output), policy-checked (no refund/discount/date\npromises, no internal jargon, length caps; violations force a handoff) and\naudited (a portal_brain_traces row + an ai.* portal_action_log entry).\n\nAutonomy per tenant (portal_brain_settings.autonomy):\n  off     - brain never runs (the rollback switch);\n  suggest - DEFAULT: the owner can ask for drafts via POST\n            /portal/brain/draft; the ingest path never fires;\n  auto    - the ingest hook may queue a reply itself when confidence >=\n            OF_BRAIN_MIN_CONFIDENCE and policy passes.\n\nv2 adds the STRUCTURED BUSINESS CONTEXT layer (the giant-prompt killer):\nthe owner stores policies / SOPs / pricing / refund + escalation rules as\nqueryable rows (portal_brain_facts) instead of pasting essays into the\nprompt. The reasoner queries them per message (tool_business_facts) and\ngrounds on them like any other tool; owners manage them via\nGET/POST/DELETE /portal/brain/facts and the Business facts card on\nConfigure AI.\n\nFail-soft everywhere: a missing LLM key, an outage or any db error makes\nthe brain step aside (None) and the B3 keyword path handles the message.\n\"\"\"\n\nimport json\nimport logging\nimport os\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n)\n\nlogger = logging.getLogger(\"omniflow.portal-brain\")\n\nbp = Blueprint(\"portal_brain\", __name__, url_prefix=\"/api/v1/portal\")\n\nSETTINGS_TABLE = \"portal_brain_settings\"\nTRACES_TABLE = \"portal_brain_traces\"\n\nAUTONOMY_LEVELS = (\"off\", \"suggest\", \"auto\")\nMAX_TOOL_CALLS = int(os.environ.get(\"OF_BRAIN_MAX_TOOL_CALLS\", \"3\") or 3)\nMIN_CONFIDENCE = float(\n    os.environ.get(\"OF_BRAIN_MIN_CONFIDENCE\", \"0.6\") or 0.6)\nMAX_DRAFT_CHARS = int(os.environ.get(\"OF_BRAIN_MAX_DRAFT_CHARS\", \"700\") or 700)\nFACTS_TABLE = \"portal_brain_facts\"\nFACTS_LIMIT = int(os.environ.get(\"OF_BRAIN_FACTS_LIMIT\", \"100\") or 100)\nFACT_KINDS = (\"policy\", \"sop\", \"pricing\", \"refund\", \"escalation\", \"hours\")\n\n_DDL_READY = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_brain_settings (\n  client_id BIGINT PRIMARY KEY,\n  autonomy TEXT NOT NULL DEFAULT 'suggest',\n  tone TEXT NOT NULL DEFAULT '',\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE TABLE IF NOT EXISTS portal_brain_traces (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  conversation_id BIGINT,\n  kind TEXT NOT NULL DEFAULT 'draft',\n  decision TEXT NOT NULL DEFAULT 'handoff',\n  grounding JSONB NOT NULL DEFAULT '{}'::jsonb,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_brain_traces\n  ON portal_brain_traces (client_id, conversation_id, id DESC);\nCREATE TABLE IF NOT EXISTS portal_brain_facts (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  kind TEXT NOT NULL DEFAULT 'policy',\n  label TEXT NOT NULL DEFAULT '',\n  content TEXT NOT NULL DEFAULT '',\n  keywords TEXT NOT NULL DEFAULT '',\n  is_active BOOLEAN NOT NULL DEFAULT TRUE,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_brain_facts\n  ON portal_brain_facts (client_id, is_active, id DESC);\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    \"\"\"Create the brain tables once per process (lazy DDL).\"\"\"\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    _DDL_READY = True\n\n\ndef _principal_or_error():\n    \"\"\"Owner/staff session required (API keys cannot touch the brain).\"\"\"\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    if principal.get(\"via_api_key\"):\n        return None, (jsonify({\"error\": {\"code\": \"forbidden\",\n                                         \"message\": \"Owner sign-in required.\"}}),\n                      403)\n    return principal, None\n\n\ndef _load_settings(cur, client_id: int) -> Dict[str, Any]:\n    cur.execute(\n        \"SELECT autonomy, tone FROM \" + portal_db._q(SETTINGS_TABLE) +\n        \" WHERE client_id = %s\",\n        (client_id,),\n    )\n    rows = portal_db.rows(cur)\n    if not rows:\n        return {\"autonomy\": \"suggest\", \"tone\": \"\"}\n    return {\"autonomy\": str(rows[0].get(\"autonomy\") or \"suggest\"),\n            \"tone\": str(rows[0].get(\"tone\") or \"\")}\n\n\n# ---------------------------------------------------------------------------\n# Tools (read-only, tenant-scoped, budgeted)\n# ---------------------------------------------------------------------------\n\ndef tool_recent_messages(cur, client_id: int, conversation_id: int,\n                         n: int = 10) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT direction, body, created_at FROM \" +\n        portal_db._q(portal_db.MSGS_TABLE) +\n        \" WHERE client_id = %s AND conversation_id = %s\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (client_id, conversation_id, max(1, min(20, n))),\n    )\n    rows = portal_db.rows(cur)\n    return [{\"direction\": str(r.get(\"direction\") or \"\"),\n             \"body\": str(r.get(\"body\") or \"\")[:300],\n             \"created_at\": str(r.get(\"created_at\") or \"\")}\n            for r in reversed(rows)]\n\n\ndef tool_customer_orders(cur, client_id: int, contact_id: str,\n                         n: int = 3) -> List[Dict[str, Any]]:\n    if not str(contact_id or \"\").strip():\n        return []\n    cur.execute(\n        \"SELECT id, total, status, paid_amount, updated_at FROM \" +\n        portal_db._q(\"portal_checkout_links\") +\n        \" WHERE client_id = %s AND contact_id = %s\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (client_id, str(contact_id), max(1, min(10, n))),\n    )\n    rows = portal_db.rows(cur)\n    return [{\"id\": int(r.get(\"id\") or 0),\n             \"total\": float(r.get(\"total\") or 0),\n             \"status\": str(r.get(\"status\") or \"\"),\n             \"paid_amount\": float(r.get(\"paid_amount\") or 0),\n             \"updated_at\": str(r.get(\"updated_at\") or \"\")}\n            for r in rows]\n\n\ndef tool_search_kb(cur, client_id: int, query: str,\n                   n: int = 3) -> List[Dict[str, Any]]:\n    text = str(query or \"\").strip()[:120]\n    if not text:\n        return []\n    cur.execute(\n        \"SELECT id, title, content FROM \" + portal_db._q(\"portal_kb_entries\") +\n        \" WHERE client_id = %s AND is_active = TRUE\"\n        \" AND (title ILIKE %s OR content ILIKE %s OR keywords ILIKE %s)\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (client_id, \"%\" + text + \"%\", \"%\" + text + \"%\", \"%\" + text + \"%\",\n         max(1, min(5, n))),\n    )\n    rows = portal_db.rows(cur)\n    return [{\"id\": int(r.get(\"id\") or 0),\n             \"title\": str(r.get(\"title\") or \"\"),\n             \"content\": str(r.get(\"content\") or \"\")[:400]}\n            for r in rows]\n\n\ndef tool_customer_profile(cur, client_id: int,\n                          contact_id: str) -> Dict[str, Any]:\n    language = None\n    try:\n        import portal_contacts\n\n        language = portal_contacts.stored_language(cur, client_id, contact_id)\n    except Exception:\n        language = None\n    return {\"language\": language}\n\n\ndef tool_business_facts(cur, client_id: int, query: str,\n                        n: int = 3) -> List[Dict[str, Any]]:\n    \"\"\"v2: query the tenant's structured business context (policies,\n    SOPs, pricing, refund/escalation rules, hours). Active rows only,\n    tenant-scoped, matched over label + content + keywords.\"\"\"\n    text = str(query or \"\").strip()[:120]\n    if not text:\n        return []\n    cur.execute(\n        \"SELECT id, kind, label, content FROM \" +\n        portal_db._q(FACTS_TABLE) +\n        \" WHERE client_id = %s AND is_active = TRUE\"\n        \" AND (label ILIKE %s OR content ILIKE %s OR keywords ILIKE %s)\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (client_id, \"%\" + text + \"%\", \"%\" + text + \"%\", \"%\" + text + \"%\",\n         max(1, min(5, n))),\n    )\n    rows = portal_db.rows(cur)\n    return [{\"id\": int(r.get(\"id\") or 0),\n             \"kind\": str(r.get(\"kind\") or \"policy\"),\n             \"label\": str(r.get(\"label\") or \"\"),\n             \"content\": str(r.get(\"content\") or \"\")[:400]}\n            for r in rows]\n\n\ndef tool_customer_memory(cur, client_id: int, contact_id: str,\n                         n: int = 3) -> List[Dict[str, Any]]:\n    \"\"\"Memory upgrade: read the customer's own memory rows (preferences,\n    notes, facts, journey position) - non-expired only, tenant-scoped,\n    read-only. Fail-soft: any problem means [] (the reply just loses\n    personalization, never breaks).\"\"\"\n    contact = str(contact_id or \"\").strip()\n    if not contact:\n        return []\n    try:\n        import portal_memory\n\n        cur.execute(\n            \"SELECT id, kind, mtype, content FROM \" +\n            portal_db._q(portal_memory.MEMORY_TABLE) +\n            \" WHERE client_id = %s AND contact_id = %s\"\n            \" AND (expires_at IS NULL OR expires_at > NOW())\"\n            \" ORDER BY id DESC LIMIT %s\",\n            (client_id, contact, max(1, min(5, n))),\n        )\n        rows = portal_db.rows(cur)\n        return [{\"id\": int(r.get(\"id\") or 0),\n                 \"kind\": str(r.get(\"kind\") or \"note\"),\n                 \"mtype\": str(r.get(\"mtype\") or \"long\"),\n                 \"content\": str(r.get(\"content\") or \"\")[:200]}\n                for r in rows]\n    except Exception:\n        return []\n\n\n# ---------------------------------------------------------------------------\n# Policy engine (deterministic post-checks)\n# ---------------------------------------------------------------------------\n\n_POLICY_FORBIDDEN = (\n    # refund / money promises\n    \"refund will\", \"will refund\", \"paise wapas\", \"money back\",\n    \"full refund\", \"100% refund\",\n    # discount promises\n    \"discount de\", \"extra discount\", \"special discount for you\",\n    \"i can give you a discount\", \"50% off\",\n    # delivery-date promises\n    \"guaranteed delivery\", \"pakka kal\", \"definitely tomorrow\",\n    # internal jargon / meta\n    \"system prompt\", \"as an ai\", \"language model\", \"database\",\n)\n\n_POLICY_MAX_NEWLINES = 8\n\n\ndef policy_check(text: str) -> List[str]:\n    \"\"\"Return the list of policy violations ([] = passes).\"\"\"\n    violations: List[str] = []\n    low = \" \" + \" \".join(str(text or \"\").lower().split()) + \" \"\n    for phrase in _POLICY_FORBIDDEN:\n        if phrase in low:\n            violations.append(\"forbidden:\" + phrase)\n    if len(str(text or \"\")) > MAX_DRAFT_CHARS:\n        violations.append(\"too_long\")\n    if str(text or \"\").count(\"\\n\") > _POLICY_MAX_NEWLINES:\n        violations.append(\"too_many_lines\")\n    return violations\n\n\n# ---------------------------------------------------------------------------\n# Reasoner: grounding + LLM + decision\n# ---------------------------------------------------------------------------\n\ndef _system_prompt(tone: str) -> str:\n    tone_line = (\"Write in this tone: \" + tone + \".\") if tone.strip() else \"\"\n    return (\n        \"You are the WhatsApp support agent of a Pakistani retail business. \"\n        \"Customers often write in Roman Urdu; reply in the customer's \"\n        \"language, short and friendly. You may ONLY use facts from the \"\n        \"provided CONTEXT - never invent orders, prices, dates or policies. \"\n        \"CONTEXT may include BUSINESS facts (policies, pricing, SOPs, \"\n        \"hours, refund and escalation rules); treat them as the owner's \"\n        \"own rules and follow them exactly. CONTEXT may also include \"\n        \"MEMORY notes about THIS customer (preferences, past issues, \"\n        \"journey position); personalize using them. CONTEXT may include \"\n        \"an AGENT persona (name + instructions); when present, answer AS \"\n        \"that agent and follow its instructions. \"\n        \"NEVER promise refunds, discounts or delivery dates; NEVER mention \"\n        \"internal systems. If the context is insufficient or the customer \"\n        \"needs a human, set needs_human=true. \" + tone_line +\n        ' Reply ONLY with JSON: {\"reply\": \"...\", \"needs_human\": false, '\n        '\"confidence\": 0.0}'\n    )\n\n\ndef _reason(cur, client_id: int, conversation_id: int, contact_id: str,\n            contact_name: str, message_text: str,\n            tone: str) -> Tuple[Optional[Dict[str, Any]], Dict[str, Any]]:\n    \"\"\"Run the budgeted tools, then one LLM call.\n\n    Returns (llm_payload_or_None, grounding_dict). Never raises beyond\n    what the callers already guard.\n    \"\"\"\n    grounding: Dict[str, Any] = {\"tools\": []}\n    context: Dict[str, Any] = {}\n    calls = 0\n\n    def budget_left() -> bool:\n        return calls < MAX_TOOL_CALLS\n\n    context[\"conversation\"] = tool_recent_messages(cur, client_id,\n                                                   conversation_id, 10)\n    calls += 1\n    orders = tool_customer_orders(cur, client_id, contact_id, 3)\n    calls += 1\n    if orders:\n        context[\"orders\"] = orders\n        grounding[\"tools\"].append(\"customer_orders\")\n    kb = tool_search_kb(cur, client_id, message_text, 3)\n    calls += 1\n    if kb:\n        context[\"kb\"] = kb\n        grounding[\"tools\"].append(\"search_kb\")\n    facts = tool_business_facts(cur, client_id, message_text, 3)\n    calls += 1\n    if facts:\n        context[\"business\"] = facts\n        grounding[\"tools\"].append(\"business_facts\")\n    memories = tool_customer_memory(cur, client_id, contact_id, 3)\n    calls += 1\n    if memories:\n        context[\"memory\"] = memories\n        grounding[\"tools\"].append(\"customer_memory\")\n    agent = None\n    try:\n        import portal_agents\n\n        agent = portal_agents.agent_for_conversation(cur, client_id,\n                                                     conversation_id)\n    except Exception:\n        agent = None\n    calls += 1\n    if agent:\n        context[\"agent\"] = {\"name\": agent.get(\"name\"),\n                            \"instructions\":\n                            str(agent.get(\"instructions\") or \"\")[:400]}\n        grounding[\"tools\"].append(\"agent_persona\")\n        grounding[\"agent_id\"] = agent.get(\"id\")\n        if str(agent.get(\"tone\") or \"\").strip():\n            tone = str(agent.get(\"tone\"))\n    profile = tool_customer_profile(cur, client_id, contact_id)\n    if profile.get(\"language\"):\n        context[\"language\"] = profile[\"language\"]\n        grounding[\"tools\"].append(\"customer_profile\")\n    grounding[\"conversation_messages\"] = len(context[\"conversation\"])\n    grounding[\"kb_ids\"] = [e[\"id\"] for e in kb]\n    grounding[\"fact_ids\"] = [f[\"id\"] for f in facts]\n    grounding[\"memory_ids\"] = [m[\"id\"] for m in memories]\n    grounding[\"order_ids\"] = [o[\"id\"] for o in orders]\n    del budget_left\n\n    context[\"customer_name\"] = str(contact_name or \"\")\n    context[\"customer_message\"] = str(message_text or \"\")\n\n    import portal_llm\n\n    payload = portal_llm.chat_json(\n        _system_prompt(tone),\n        json.dumps(context, ensure_ascii=False, default=str),\n        max_tokens=300,\n    )\n    grounding[\"llm_called\"] = payload is not None\n    return payload, grounding\n\n\ndef _decide(payload: Optional[Dict[str, Any]],\n            grounding: Dict[str, Any]) -> Tuple[str, str, Dict[str, Any]]:\n    \"\"\"Map the LLM payload + policy to (decision, reply, grounding).\"\"\"\n    if not isinstance(payload, dict):\n        grounding[\"reason\"] = \"llm_unavailable\"\n        return \"handoff\", \"\", grounding\n    try:\n        confidence = float(payload.get(\"confidence\") or 0)\n    except Exception:\n        confidence = 0\n    reply = str(payload.get(\"reply\") or \"\").strip()\n    needs_human = bool(payload.get(\"needs_human\"))\n    grounding[\"confidence\"] = confidence\n    if needs_human:\n        grounding[\"reason\"] = \"needs_human\"\n        return \"handoff\", \"\", grounding\n    if confidence < MIN_CONFIDENCE:\n        grounding[\"reason\"] = \"low_confidence\"\n        return \"handoff\", \"\", grounding\n    violations = policy_check(reply)\n    grounding[\"policy_violations\"] = violations\n    if violations:\n        grounding[\"reason\"] = \"policy:\" + violations[0]\n        return \"handoff\", \"\", grounding\n    if not reply:\n        grounding[\"reason\"] = \"empty_reply\"\n        return \"handoff\", \"\", grounding\n    return \"send\", reply[:MAX_DRAFT_CHARS], grounding\n\n\ndef _write_trace(cur, client_id: int, conversation_id: int, kind: str,\n                 decision: str, grounding: Dict[str, Any]) -> None:\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(TRACES_TABLE) +\n        \" (client_id, conversation_id, kind, decision, grounding)\"\n        \" VALUES (%s, %s, %s, %s, CAST(%s AS JSONB))\",\n        (client_id, conversation_id, kind, decision,\n         json.dumps(grounding, ensure_ascii=False, default=str)),\n    )\n\n\n# ---------------------------------------------------------------------------\n# Ingest hook (autonomy == auto only) + owner draft API\n# ---------------------------------------------------------------------------\n\ndef maybe_answer(client_id, conversation_id, contact_id, contact_name,\n                 body, conn) -> Optional[bool]:\n    \"\"\"Ingest hook: answer under 'auto' autonomy; return True when the\n    brain queued the reply (the one-reply law claims it as 'brain').\"\"\"\n    text = str(body or \"\").strip()\n    if not text:\n        return None\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            settings = _load_settings(cur, client_id)\n            if settings.get(\"autonomy\") != \"auto\":\n                return None\n            payload, grounding = _reason(\n                cur, client_id, int(conversation_id or 0),\n                str(contact_id or \"\"), str(contact_name or \"\"), text,\n                str(settings.get(\"tone\") or \"\"))\n            decision, reply, grounding = _decide(payload, grounding)\n            _write_trace(cur, client_id, int(conversation_id or 0),\n                         \"ingest_answer\", decision, grounding)\n            if decision != \"send\":\n                return None\n            payload_out = {\n                \"external_user_id\": str(contact_id or \"\"),\n                \"body\": reply,\n                \"conversation_id\": conversation_id,\n                \"source\": \"ai_brain\",\n            }\n            if str(contact_name or \"\").strip():\n                payload_out[\"target_display_name\"] = str(contact_name)\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(portal_db.CMD_TABLE) +\n                \" (client_id, channel, action, payload, status,\"\n                \" requested_by, created_at, updated_at) \"\n                \"VALUES (%s, 'whatsapp', 'send_message',\"\n                \" CAST(%s AS JSONB), 'pending', NULL, NOW(), NOW()) \"\n                \"RETURNING id\",\n                (client_id, json.dumps(payload_out)),\n            )\n            portal_db.log_action(\n                cur, client_id, \"ai.answer\", \"automation\",\n                None, conversation_id,\n                \"Brain answered (tools: \" +\n                \",\".join(grounding.get(\"tools\") or [\"none\"]) + \").\",\n            )\n            return True\n    except Exception as error:\n        logger.warning(\"brain maybe_answer failed: %s\", error)\n        return None\n\n\ndef draft_reply(cur, client_id: int, conversation_id: int,\n                message_text: str = \"\") -> Dict[str, Any]:\n    \"\"\"Owner-facing draft (autonomy 'suggest'): never queues a send.\"\"\"\n    _ensure_ddl(cur)\n    settings = _load_settings(cur, client_id)\n    payload, grounding = _reason(\n        cur, client_id, conversation_id, \"\", \"\", message_text,\n        str(settings.get(\"tone\") or \"\"))\n    decision, reply, grounding = _decide(payload, grounding)\n    _write_trace(cur, client_id, conversation_id, \"draft\", decision,\n                 grounding)\n    portal_db.log_action(\n        cur, client_id, \"ai.draft\", \"human\",\n        None, conversation_id,\n        \"Brain draft requested (\" + decision + \").\",\n    )\n    result = {\"decision\": decision,\n              \"draft\": reply,\n              \"grounding\": grounding,\n              \"autonomy\": settings.get(\"autonomy\")}\n    # KB auto-draft (owner decision, admin panel): when on, a draft also\n    # ships a saveable knowledge-base entry so good answers stop being\n    # one-offs. Fail-soft: the plain draft is always there.\n    try:\n        import platform_settings\n        if platform_settings.flag(\"kb_autodraft\") and reply:\n            result[\"kb_entry\"] = {\n                \"title\": (message_text or \"\").strip()[:120]\n                         or \"Saved answer\",\n                \"content\": str(reply),\n            }\n    except Exception:\n        pass\n    return result\n\n\n# ---------------------------------------------------------------------------\n# Owner API: settings / draft / trace\n# ---------------------------------------------------------------------------\n\n@bp.get(\"/brain/settings\")\ndef get_brain_settings():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            settings = _load_settings(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"settings\": settings}), 200\n\n\n@bp.put(\"/brain/settings\")\ndef put_brain_settings():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    autonomy = payload.get(\"autonomy\")\n    tone = payload.get(\"tone\")\n    if autonomy not in AUTONOMY_LEVELS:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"autonomy must be one of off|suggest|auto.\",\n        }}), 400\n    if tone is not None and not isinstance(tone, str):\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"tone must be a string.\",\n        }}), 400\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(SETTINGS_TABLE) +\n                \" (client_id, autonomy, tone, updated_at)\"\n                \" VALUES (%s, %s, %s, NOW())\"\n                \" ON CONFLICT (client_id) DO UPDATE SET\"\n                \" autonomy = EXCLUDED.autonomy,\"\n                \" tone = EXCLUDED.tone, updated_at = NOW()\",\n                (client_id, autonomy, str(tone or \"\")[:200]),\n            )\n            portal_db.log_action(\n                cur, client_id, \"ai.settings\", \"human\",\n                None, None,\n                \"Brain autonomy set to \" + str(autonomy) + \".\",\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"settings\": {\"autonomy\": autonomy,\n                                 \"tone\": str(tone or \"\")}}), 200\n\n\n@bp.post(\"/brain/draft\")\ndef draft_brain_reply():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    try:\n        conversation_id = int(payload.get(\"conversation_id\") or 0)\n    except Exception:\n        conversation_id = 0\n    if conversation_id <= 0:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"conversation_id (positive integer) is required.\",\n        }}), 400\n    message_text = str(payload.get(\"message\") or \"\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"SELECT 1 FROM \" + portal_db._q(portal_db.CONV_TABLE) +\n                \" WHERE id = %s AND client_id = %s LIMIT 1\",\n                (conversation_id, client_id),\n            )\n            if not portal_db.rows(cur):\n                conn.rollback()\n                return jsonify({\"error\": {\n                    \"code\": \"not_found\",\n                    \"message\": \"No such conversation in this workspace.\",\n                }}), 404\n            result = draft_reply(cur, client_id, conversation_id,\n                                 message_text)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify(result), 200\n\n\n@bp.get(\"/brain/trace\")\ndef list_brain_traces():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    try:\n        conversation_id = int(request.args.get(\"conversation_id\") or 0)\n    except Exception:\n        conversation_id = 0\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            sql = (\"SELECT id, conversation_id, kind, decision, grounding,\"\n                   \" created_at FROM \" + portal_db._q(TRACES_TABLE) +\n                   \" WHERE client_id = %s\")\n            params: Tuple[Any, ...] = (client_id,)\n            if conversation_id > 0:\n                sql += \" AND conversation_id = %s\"\n                params = (client_id, conversation_id)\n            sql += \" ORDER BY id DESC LIMIT 10\"\n            cur.execute(sql, params)\n            rows = portal_db.rows(cur)\n        conn.commit()\n    finally:\n        conn.close()\n    out = [{\"id\": int(r.get(\"id\") or 0),\n            \"conversation_id\": r.get(\"conversation_id\"),\n            \"kind\": str(r.get(\"kind\") or \"\"),\n            \"decision\": str(r.get(\"decision\") or \"\"),\n            \"grounding\": r.get(\"grounding\"),\n            \"created_at\": str(r.get(\"created_at\") or \"\")}\n           for r in rows]\n    return jsonify({\"traces\": out}), 200\n\n\n# ---------------------------------------------------------------------------\n# v2: structured business context (facts) - owner CRUD\n# ---------------------------------------------------------------------------\n\ndef _shape_fact(row: Dict[str, Any]) -> Dict[str, Any]:\n    return {\"id\": int(row.get(\"id\") or 0),\n            \"kind\": str(row.get(\"kind\") or \"policy\"),\n            \"label\": str(row.get(\"label\") or \"\"),\n            \"content\": str(row.get(\"content\") or \"\"),\n            \"keywords\": str(row.get(\"keywords\") or \"\"),\n            \"is_active\": bool(row.get(\"is_active\")),\n            \"updated_at\": str(row.get(\"updated_at\") or \"\")}\n\n\n@bp.get(\"/brain/facts\")\ndef list_brain_facts():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"SELECT id, kind, label, content, keywords, is_active,\"\n                \" updated_at FROM \" + portal_db._q(FACTS_TABLE) +\n                \" WHERE client_id = %s\"\n                \" ORDER BY is_active DESC, id DESC LIMIT %s\",\n                (client_id, max(1, min(500, FACTS_LIMIT))),\n            )\n            rows = portal_db.rows(cur)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"facts\": [_shape_fact(r) for r in rows]}), 200\n\n\n@bp.post(\"/brain/facts\")\ndef save_brain_fact():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    fact_id = 0\n    try:\n        fact_id = int(payload.get(\"id\") or 0)\n    except Exception:\n        fact_id = 0\n    kind = str(payload.get(\"kind\") or \"policy\")\n    label = str(payload.get(\"label\") or \"\").strip()\n    content = str(payload.get(\"content\") or \"\").strip()\n    keywords = str(payload.get(\"keywords\") or \"\").strip()\n    is_active = payload.get(\"is_active\", True)\n    if not isinstance(is_active, bool):\n        is_active = bool(is_active)\n    if kind not in FACT_KINDS:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"kind must be one of \" + \"|\".join(FACT_KINDS) + \".\",\n        }}), 400\n    if not label or len(label) > 120:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"label is required (max 120 characters).\",\n        }}), 400\n    if not content or len(content) > 2000:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"content is required (max 2000 characters).\",\n        }}), 400\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            if fact_id > 0:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(FACTS_TABLE) +\n                    \" SET kind = %s, label = %s, content = %s,\"\n                    \" keywords = %s, is_active = %s, updated_at = NOW()\"\n                    \" WHERE id = %s AND client_id = %s RETURNING id\",\n                    (kind, label[:120], content[:2000], keywords[:200],\n                     is_active, fact_id, client_id),\n                )\n                rows = portal_db.rows(cur)\n                if not rows:\n                    conn.rollback()\n                    return jsonify({\"error\": {\n                        \"code\": \"not_found\",\n                        \"message\": \"No such fact in this workspace.\",\n                    }}), 404\n                action = \"updated\"\n            else:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(FACTS_TABLE) +\n                    \" (client_id, kind, label, content, keywords,\"\n                    \" is_active, updated_at)\"\n                    \" VALUES (%s, %s, %s, %s, %s, %s, NOW())\"\n                    \" RETURNING id\",\n                    (client_id, kind, label[:120], content[:2000],\n                     keywords[:200], is_active),\n                )\n                rows = portal_db.rows(cur)\n                action = \"created\"\n            portal_db.log_action(\n                cur, client_id, \"brain.facts\", \"human\",\n                None, None,\n                \"Business fact \" + action + \": \" + label[:80] + \".\",\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"fact\": {\"id\": int(rows[0].get(\"id\") or 0),\n                             \"kind\": kind, \"label\": label,\n                             \"content\": content, \"keywords\": keywords,\n                             \"is_active\": is_active}}), 200\n\n\n@bp.delete(\"/brain/facts\")\ndef delete_brain_fact():\n    \"\"\"Soft delete (data-preserving): the row just goes inactive and the\n    owner can re-activate it from the same card.\"\"\"\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    try:\n        fact_id = int(request.args.get(\"id\") or 0)\n    except Exception:\n        fact_id = 0\n    if fact_id <= 0:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"id (positive integer) is required.\",\n        }}), 400\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"UPDATE \" + portal_db._q(FACTS_TABLE) +\n                \" SET is_active = FALSE, updated_at = NOW()\"\n                \" WHERE id = %s AND client_id = %s RETURNING id\",\n                (fact_id, client_id),\n            )\n            rows = portal_db.rows(cur)\n            if not rows:\n                conn.rollback()\n                return jsonify({\"error\": {\n                    \"code\": \"not_found\",\n                    \"message\": \"No such fact in this workspace.\",\n                }}), 404\n            portal_db.log_action(\n                cur, client_id, \"brain.facts\", \"human\",\n                None, None,\n                \"Business fact archived (id \" + str(fact_id) + \").\",\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True}), 200\n");

